function s(n){return n.paymentExemption==="half"||n.paymentExemption==="full"||n.paymentExemption==="none"?n.paymentExemption:n.paymentExempt?"full":"none"}function i(n){let t=s(n);return t==="full"?0:t==="half"?.5:1}function x(n){return s(n)==="full"}function P(n){return n.filter(t=>t.active!==!1&&i(t)>0)}function p(n){return n.filter(t=>t.active!==!1).reduce((t,e)=>t+i(e),0)}function c(n,t){return!t||t<=0?0:n/t}function o(n){return Math.round((Number(n)||0)*100)/100}function y(n,t){let e=n.installments||1;return c(n.totalAmount,t)/e}function f(n,t,e=1){let r=Number(n.installments)||1,m=n.installmentAmounts;return m&&m.length>=r?o(m[e-1]??0):o(y(n,t))}function g(n,t,e,r=1){return o(f(n,p(t),r)*i(e))}function d(n,t){let e=Number(n.installments)||0,r=Array.from({length:e},(a,u)=>f(n,t,u+1));return r.every(a=>Math.abs(a-r[0])<.01)?`${e} x ${l(r[0]??0)}`:r.map((a,u)=>`C${u+1} ${l(a)}`).join(" \xB7 ")}function l(n){return new Intl.NumberFormat("es-AR",{style:"currency",currency:"ARS",maximumFractionDigits:0}).format(n||0)}function E(n){return n?Number.isInteger(n)?String(n):n.toFixed(1).replace(".",","):"0"}function h(n){return n==="full"?"Liberado":n==="half"?"Liberado 50%":""}function b(n,t,e){return`${n}-${t}-${e}`}function I(n){let t=new Map;for(let e of n){let r=b(e.playerId,e.tournamentId,e.installmentNumber);t.set(r,(t.get(r)??0)+(Number(e.amount)||0))}return t}function N(n,t){return t<=1||n+1>=t?"paid":n<=0?"unpaid":"partial"}function T(n,t){return Math.max(0,Math.round((n-t)*100)/100)}function A(n,t,e,r,m){return n.filter(a=>a.playerId===t&&a.tournamentId===e&&a.installmentNumber===r&&a.id!==m).reduce((a,u)=>a+(Number(u.amount)||0),0)}export{s as a,i as b,x as c,P as d,p as e,c as f,o as g,f as h,g as i,d as j,E as k,h as l,b as m,I as n,N as o,T as p,A as q};
